type UserWithPosts struct {
	User
	Posts runtime.Page[Post]
}

func (c *Client) GetUserWithPosts(ctx context.Context, key UserKey, page runtime.PageRequest) (UserWithPosts, error) {
	value, ok, err := c.GetUser(ctx, key)
	if err != nil {
		return UserWithPosts{}, err
	}
	if !ok {
		return UserWithPosts{}, fmt.Errorf("dynamox: User not found")
	}
	result := UserWithPosts{User: value}
	related, err := c.post.Query(ctx, runtime.QueryRequest{IndexName: "ByAuthor", PartitionName: "authorId", PartitionValue: value.ID, SortName: "createdAt", Page: page, GlobalIndex: true})
	if err != nil {
		return UserWithPosts{}, err
	}
	result.Posts = related
	return result, nil
}

type PostWithAuthor struct {
	Post
	Author User
}

func (c *Client) GetPostWithAuthor(ctx context.Context, key PostKey) (PostWithAuthor, error) {
	value, ok, err := c.GetPost(ctx, key)
	if err != nil {
		return PostWithAuthor{}, err
	}
	if !ok {
		return PostWithAuthor{}, fmt.Errorf("dynamox: Post not found")
	}
	result := PostWithAuthor{Post: value}
	related, ok, err := c.GetUser(ctx, UserKey{ID: value.AuthorID})
	if err != nil {
		return PostWithAuthor{}, err
	}
	if !ok {
		return PostWithAuthor{}, fmt.Errorf("dynamox: related User not found")
	}
	result.Author = related
	return result, nil
}

type PostWithEditor struct {
	Post
	Editor *User
}

func (c *Client) GetPostWithEditor(ctx context.Context, key PostKey) (PostWithEditor, error) {
	value, ok, err := c.GetPost(ctx, key)
	if err != nil {
		return PostWithEditor{}, err
	}
	if !ok {
		return PostWithEditor{}, fmt.Errorf("dynamox: Post not found")
	}
	result := PostWithEditor{Post: value}
	if value.EditorID == nil {
		return result, nil
	}
	related, ok, err := c.GetUser(ctx, UserKey{ID: *value.EditorID})
	if err != nil {
		return PostWithEditor{}, err
	}
	if !ok {
		return PostWithEditor{}, fmt.Errorf("dynamox: related User not found")
	}
	result.Editor = &related
	return result, nil
}
